# === Patcher logic ===
text = FILE.read_text(encoding="utf-8")

id_pattern = re.compile(r'id:\s*"([^"]+)"', re.M)
ids = [(m.group(1), m.start()) for m in id_pattern.finditer(text)]

block_re = re.compile(r'(descriptionAdvanced:\s*\{)(.*?)(\}\s*,\s*factsAdvanced)', re.S)
lang_re = re.compile(r'(de|hu|ro|en)\s*:\s*"((?:[^"\\]|\\.)*)"', re.S)

def js_string(s: str) -> str:
    """Escape a Python string for embedding in a JS double-quoted literal."""
    return s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")

# Build replacement: walk POIs in reverse so offsets stay valid
poi_ranges = []
for i, (poi_id, start) in enumerate(ids):
    end = ids[i+1][1] if i+1 < len(ids) else len(text)
    poi_ranges.append((poi_id, start, end))

new_text = text
fills_count = 0
poi_count = 0
fill_log = []

for poi_id, start, end in reversed(poi_ranges):
    block = new_text[start:end]
    bm = block_re.search(block)
    if not bm:
        continue
    inner = bm.group(2)
    existing = {"de":"", "hu":"", "ro":"", "en":""}
    for lm in lang_re.finditer(inner):
        existing[lm.group(1)] = lm.group(2)

    new_for_poi = CONTENT.get(poi_id, {})
    final = {}
    poi_filled_langs = []
    for lg in ("de", "hu", "ro", "en"):
        if len(existing[lg]) >= 50:
            final[lg] = existing[lg]
        elif lg in new_for_poi:
            final[lg] = new_for_poi[lg]
            poi_filled_langs.append(lg)
        else:
            # keep existing (even if short/empty) — should not happen for our targets
            final[lg] = existing[lg]

    if not poi_filled_langs:
        continue

    # Build new descriptionAdvanced inner
    new_inner = (
        '\n      de: "' + js_string(final["de"]) + '",\n'
        '      hu: "' + js_string(final["hu"]) + '",\n'
        '      ro: "' + js_string(final["ro"]) + '",\n'
        '      en: "' + js_string(final["en"]) + '"\n    '
    )
    new_block_str = bm.group(1) + new_inner + bm.group(3)
    # Replace within block
    new_block = block[:bm.start()] + new_block_str + block[bm.end():]
    new_text = new_text[:start] + new_block + new_text[end:]

    poi_count += 1
    fills_count += len(poi_filled_langs)
    fill_log.append((poi_id, poi_filled_langs))

FILE.write_text(new_text, encoding="utf-8")

print(f"Filled {poi_count} POIs, total {fills_count} language slots.")
for pid, langs in reversed(fill_log):
    print(f"  {pid}: {','.join(langs)}")
